def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/astronomy/input/omni2_low_res/omni2.txt'
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        txt = f.read()
    return pd.DataFrame([{'path': path, 'content': txt}])

def load() -> pd.DataFrame:
    import pandas as pd, glob
    pattern = 'data/astronomy/input/swarmb/SB_DNS_POD_2024_*.txt'
    files = sorted(glob.glob(pattern))
    if len(files) == 0:
        raise FileNotFoundError(f'No files matched: {pattern}')
    return pd.DataFrame({'path': files})

def process(swarmBFilesList) -> pd.DataFrame:
    import pandas as pd
    path = swarmBFilesList['path'].iloc[0]
    lines = []
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        for i in range(60):
            line = f.readline()
            if not line:
                break
            lines.append({'path': path, 'line_no': i+1, 'line': line.rstrip('\n')})
    return pd.DataFrame(lines)

