        # keep rows with enough tokens (>=6)
        nonnull = df.drop(columns=['source_file','row'], errors='ignore').notna().sum(axis=1)
        df = df.loc[nonnull >= 6].reset_index(drop=True)
        dfs.append(df)

    if not dfs:
        return pd.DataFrame()
    out = pd.concat(dfs, ignore_index=True, sort=False)
    return out

