def process(swarmBFilesList) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    paths = sorted(swarmBFilesList['path'].dropna().tolist())
    if not paths:
        return pd.DataFrame(columns=['source_file','row'])

    dfs = []
    for path in paths:
        try:
            df = pd.read_csv(path, sep=r'\s+', header=None, comment='#', dtype=str, engine='python')
        except Exception:
            # very defensive fallback
            with open(path, 'r', errors='replace') as f:
                rows = []
                for line in f:
                    if not line.strip() or line.lstrip().startswith('#'):
                        continue
                    rows.append(line.strip().split())
            if not rows:
                continue
            maxlen = max(len(r) for r in rows)
            rows = [r + [None]*(maxlen-len(r)) for r in rows]
            df = pd.DataFrame(rows)

        # drop totally empty
        df = df.dropna(how='all')
        # keep rows that look like data (at least 6 fields for datetime)
        nonnull = df.notna().sum(axis=1)
        df = df.loc[nonnull >= 6].copy()

        df['source_file'] = path
        df['row'] = np.arange(len(df))
        dfs.append(df)

    if not dfs:
        return pd.DataFrame(columns=['source_file','row'])

    out = pd.concat(dfs, ignore_index=True)
    return out

